	-- {npc:255693} Kala'th
[ "The burnt buildings stand in the meadows east of {npc:255693}: the nails and brackets lie among the rubble." ] = "Die verbrannten Gebäude stehen auf den Wiesen östlich von {npc:255693}: die Nägel und Winkel liegen unter dem Trümmerhaufen.",

