	-- {npc:255771} Whisperfur · {area:16868} Mourning's Rest
	["The last kitten, {npc:255771}, plays at the southern end of {area:16868}."] = "Das letzte Kätzchen, {npc:255771}, spielt am südlichen Ende von {area:16868}.",

