	-- {area:16867} Shrine of Aviana · {npc:260825} Phoebe Highfeather
[ "East from the Cradle towards the {area:16867}, where the Wormwing harpies nest: a corrupted growth on the shrine's western slope starts a quest for {npc:260825}." ] = "Östlich von der Wiege Richtung {area:16867}, wo die Wormwing-Harpyien nisten: ein verseuchter Auswuchs am westlichen Hang des Schreins startet eine Quest für {npc:260825}.",
[ "remove the corrupted knots on the trees just north-west of the shrine, on your way" ] = "Entferne die verseuchten Verwerfungen an den Bäumen nordwestlich des Schreins, auf dem Weg",

	-- Step 110: Skylord Omnuron
	-- {npc:254131} Skylord Omnuron · {npc:260825} Phoebe Highfeather · {area:16867} Shrine of Aviana
	["{npc:254131} and {npc:260825} stand together at the {area:16867}."] = "{npc:254131} und {npc:260825} stehen gemeinsam am {area:16867}.",
	-- {quest:92500} A Bit of the Sky · {npc:256222} Ketharas
	["{quest:92500}: for {npc:256222}, later in this guide"] = "{quest:92500}: für {npc:256222}, später in diesem Guide.",

	-- Step 112: The Shrine of Aviana
	-- {area:16867} Shrine of Aviana
	["The {area:16867}"] = "Das {area:16867}.",

	-- Step 113: The harpy grounds
	["The harpy grounds"] = "Die Harpyen-Gelände.",
	-- {npc:256660} Thobon Sapclaw · {object:650219} Jewel of the Horizon (no name in this language: may be words) · {npc:260826} Zarrat Wormwing
[ "The Wormwing harpies nest on the slopes north-west of the shrine. They drop the pinfeathers and {npc:256660}'s amulets; the bangles lie in their nests, the {object:650219} in a nest on the western slope, and {npc:260826}, who has Omnuron's spear, is among them. The corrupted knots grow on the trees just north-west of the shrine." ] = "Die Wormwing-Harpyien nisten auf den Hängen nordwestlich des Schreins. Sie lassen die Schwanzfedern und {npc:256660}s Amulett fallen; die Armreife liegen in ihren Nestern, das {object:650219} in einem Nest am westlichen Hang, und {npc:260826}, der Omnurons Speer hat, ist unter ihnen. Die verseuchten Verwerfungen wachsen an den Bäumen nordwestlich des Schreins.",

	-- Step 115: The Deadwood camps
	["The Deadwood camps"] = "Die Deadwood-Höhlen.",
	-- {quest:92446} Head Scratcher
[ "South-west back towards Barkskin Burrow: the Deadwood camps on the slopes east of the burrow hold the Totemics and Fel-Tenders. An elite named {quest:92446} (level 60) may roam the camps' eastern end." ] = "Südwestlich zurück Richtung Barkskin Burrow: die Deadwood-Lager auf den Hängen östlich der Höhle enthalten die Totemisten und Fel-Verwalter. Ein Elite namens {quest:92446} (Stufe 60) streift möglicherweise das östliche Ende der Lager.",

	-- Step 116: Head Scratcher
	-- {quest:92446} Head Scratcher · {npc:244511} Zet'gan
[ "{quest:92446} is elite (level 60 in our data): grouping up is advised. Put {npc:244511}'s rabbit carcass down in the woods at the camps' eastern end, where the Horde players in our recordings fought him, and take his claws." ] = "{quest:92446} ist Elite (Stufe 60 in unseren Daten): ein Gruppenverband ist ratsam. Leg {npc:244511}s Kaninchenkadaver im Wald am östlichen Ende der Lager ab, wo die Hordenspieler in unseren Aufzeichnungen ihn bekämpften, und nimm seine Klauen.",

	-- Step 117: Barkskin Burrow
	-- {npc:260661} Suma Mossmane · {npc:256660} Thobon Sapclaw
	["Into the burrow for the elders, {npc:260661} and {npc:256660}."] = "Ins Burrow für die Ältesten, {npc:260661} und {npc:256660}.",

	-- Step 118: Galvinquam Leafsyre
	-- {area:17145} Cradle of Tranquility · {npc:267109} Galvinquam Leafsyre · {npc:255683} Shalla'kal
[ "North-east into the {area:17145}: {npc:267109} rests in the ruins south of {npc:255683}, on your way." ] = "Nordöstlich in die {area:17145}: {npc:267109} ruht in den Ruinen südlich von {npc:255683}, auf dem Weg.",
