	-- Step 119: Jereman
	-- {npc:267158} Jereman
[ "On to the old bridge over the Cradle: touch the crow effigy on it and {npc:267158} appears again." ] = "Weiter zur alten Brücke über die Wiege: berühre das Krähenbildnis darauf, und {npc:267158} erscheint erneut.",
