[ "East up to the {area:16849}, the druids' camp. {npc:41861}, the flight master, stands at its north end; {npc:264795}, {npc:243855} and {npc:254915} along the path south; {npc:40833} indoors next to Thisalee; {npc:243815}, the innkeeper, at the south-east end." ] = "Östlich hinauf zu {area:16849}, dem Druidenlager. {npc:41861}, der Flugmeister, steht am Nordende; {npc:264795}, {npc:243855} und {npc:254915} am Weg nach Süden; {npc:40833} drinnen neben Thisalee; {npc:243815}, der Gastwirt, am südöstlichen Ende.",
	-- {npc:41861} Fayran Elthas
	["{npc:41861}, at the flight point"] = "{npc:41861}, am Flugpunkt.",
	-- {npc:243815} Sebelia · {quest:93197} Mending Communications · {npc:11118} Innkeeper Vizzie · {area:2255} Everlook
	["{npc:243815}: {quest:93197}: for {npc:11118} in {area:2255}, at the end"] = "{npc:243815}: {quest:93197}: für {npc:11118} in {area:2255}, am Ende.",

	-- Step 135: As the Crow Flies
	-- {npc:254915} Thisalee Crow · {npc:263406} Elaena Moonwhisper
	["{npc:254915}, at the Summit, for {npc:263406}'s message."] = "{npc:254915}, am Summit, für {npc:263406}'s Botschaft.",

	-- Step 136: The Summit's Blackthorne quests
	["The Summit's Blackthorne quests"] = "Die Blackthorn-Quests des Summits.",
	-- {npc:260674} Ve'han Talongrasp
[ "A group stop: the Blackthorne camps north-east of the Summit hold elite Outrunners, Priests and a Courier (60) as often as the Cultists and Adepts, with {npc:260674} (60, elite) in the middle and Ghansurok (61, elite) on the ridge. Grouping up is encouraged, look for people to do it with. Skip these if you are alone." ] = "Ein Gruppenstopp: die Blackthorne-Lager nordöstlich des Gipfels enthalten genauso oft Elite-Vorläufer, -Priester und einen Kurier (60) wie Kultisten und Adepten, mit {npc:260674} (60, Elite) in der Mitte und Ghansurok (61, Elite) auf dem Grat. Ein Gruppenverband ist angeraten, such dir Leute dafür. Überspringe sie, wenn du allein bist.",

	-- Step 137: Fly to the Tainted Foothills
	-- {npc:260626} Bluebell · {npc:249235} Kaylaena Springwhisper · {npc:256222} Ketharas
